from typing import List

class Solution:
    def countStableSubsequences(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        # A subsequence is stable if adjacent elements alternate parities
        # dp0: ends with even, dp1: ends with odd
        dp0, dp1 = 0, 0

        for x in nums:
            if x % 2 == 0:
                # Even number can extend any odd subsequence, or start a new subsequence
                dp0 = (dp0 + dp1 + 1) % MOD
            else:
                # Odd number can extend any even subsequence, or start a new subsequence
                dp1 = (dp1 + dp0 + 1) % MOD

        return (dp0 + dp1) % MOD

#include <vector>

class Solution {
public:
    int countStableSubsequences(std::vector<int>& nums) {
        long long MOD = 1000000007;
        long long dp0 = 0, dp1 = 0;

        for (int x : nums) {
            if (x % 2 == 0) {
                dp0 = (dp0 + dp1 + 1) % MOD;
            } else {
                dp1 = (dp1 + dp0 + 1) % MOD;
            }
        }
        return (dp0 + dp1) % MOD;
    }
};

