var countStableSubsequences = function(nums) {
    const MOD = 1000000007n;
    let dp0 = 0n, dp1 = 0n;

    for (const x of nums) {
        if (x % 2 === 0) {
            dp0 = (dp0 + dp1 + 1n) % MOD;
